SELECT DATE_TRUNC('MONTH', products.launch_date) AS launch_month, SUM(store_sales.units) AS total_units FROM store_sales RIGHT JOIN products ON store_sales.product_id = products.id LEFT JOIN suppliers ON suppliers.id = products.supplier_id WHERE products.cost BETWEEN 450 AND 490 GROUP BY DATE_TRUNC('MONTH', products.launch_date) HAVING SUM(store_sales.units) >= 220 ORDER BY total_units DESC;
